#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long computeRecursive(long long x, long long y, long long total, int type, vector<map<long long, long long>> &cacheMap) {
    if (cacheMap[type].count(total)) {
        return cacheMap[type][total];
    }
    if (total == 1) {
        return (type == 0) ? x : y;
    }
    if (total % 2 == 1) {
        long long res = (x * computeRecursive(x, y, total - 1, type, cacheMap) + y * computeRecursive(x, y, total - 1, (type + 1) % 2, cacheMap)) % MOD;
        cacheMap[type][total] = res;
        return res;
    } else {
        long long half = total / 2;
        long long ch = computeRecursive(x, y, half, 0, cacheMap);
        long long nch = computeRecursive(x, y, half, 1, cacheMap);
        long long ans;
        if (type == 0) {
            ans = (ch * ch + nch * nch) % MOD;
        } else {
            ans = (2 * ch * nch) % MOD;
        }
        cacheMap[type][total] = ans;
        return ans;
    }
}

long long computeCombination(long long x, long long st) {
    if (st == 0) return 1;
    if (st == 1) return x;
    long long half = st / 2;
    long long res = computeCombination(x, half);
    if (st % 2 == 0) {
        return (res * res) % MOD;
    } else {
        return ((res * res) % MOD * x) % MOD;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, p, q;
    cin >> n >> m >> p >> q;
    long long segment = q - p + 1;
    if (p % 2 == 0) {
        segment = segment - segment / 2;
    } else {
        segment /= 2;
    }
    long long otherSegment = (q - p + 1) - segment;
    vector<map<long long, long long>> cacheMap(2);
    if (((n & m) % 2) == 0) {
        long long result = computeRecursive(segment, otherSegment, n * m, 0, cacheMap);
        cout << result << "\n";
    } else {
        long long result = computeCombination(segment + otherSegment, n * m);
        cout << result << "\n";
    }
    return 0;
}
